window.products.push({"id":1003424,"name":"Kobodon Metal Wax Warmer Candle Wax Warmer, Wax Warmer for Scented Wax,2-in-1 Electric Wax Melter and Fragrance Wax Melt Warmer with 5 Pieces Wax Warm","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71N6gSKZ10L._AC_SL1500_.jpg","description":"Specifications: Material: PP+Metal Product Size:4.1*4.1*3.1 in Weight: 0.52 pounds Rated Voltage and Power: 120V, 40W Packaging Content: 1 x Electric Candle Wax Warmer 1 x Bulb 5 x wax warmer liner Instruction: 1. Put scented fragrance essential oil or wax tart in the lid. 2. Plug in power supply, turn on the in-line switch and the fragrance is all ready to fill your room. 3. Put it where your children or pets cannot easily touch in case of burning, because when the bulb is working it heats up the ceramic lid and the lampshade. 4. Don't touch the ceramic lid or the ceramic sides until several hours after turning it off.","images":["https://m.media-amazon.com/images/I/71N6gSKZ10L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"kobodon","source_asin":"B09Q2RXF3J","category_path":"Home & Kitchen"},"sku":"BM-1003424","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09Q2RXF3J","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09Q2RXF3J","price_pending":true,"merchant_ready":false});
